import{_ as t,a as d,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse(`{"title":"Raise a GDPR Request","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-gdpr-request","title":"Raise a GDPR Request","description":"Raise a new GDPR data request (delete or update) for the authenticated customer.","query":"mutation CreateGdprRequest(\\n  $type: String!\\n  $message: String!\\n) {\\n  createGdprRequest(\\n    input: {\\n      type: $type\\n      message: $message\\n    }\\n  ) {\\n    gdprRequest {\\n      _id\\n      type\\n      status\\n      message\\n      email\\n      revokedAt\\n      createdAt\\n      updatedAt\\n      successMessage\\n      customer {\\n        _id\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"type\\": \\"delete\\",\\n  \\"message\\": \\"Please delete my account data.\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createGdprRequest\\": {\\n      \\"gdprRequest\\": {\\n        \\"_id\\": 12,\\n        \\"type\\": \\"delete\\",\\n        \\"status\\": \\"pending\\",\\n        \\"message\\": \\"Please delete my account data.\\",\\n        \\"email\\": \\"jane@example.com\\",\\n        \\"revokedAt\\": null,\\n        \\"createdAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n        \\"updatedAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n        \\"successMessage\\": \\"Your GDPR data request has been raised successfully.\\",\\n        \\"customer\\": {\\n          \\"_id\\": 7\\n        }\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"GDPR disabled","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before raising a request"},{"error":"type required","cause":"The type field is missing or not one of delete / update","solution":"Provide a valid type — either \\"delete\\" or \\"update\\""},{"error":"message required","cause":"The message field is missing","solution":"Provide a message describing the request"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.md","filePath":"api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.md","lastUpdated":1787290888000}`),s={name:"api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.md"};function o(i,e,n,u,c,l){return a(),d("div",null,e[0]||(e[0]=[r('<h1 id="raise-a-gdpr-request" tabindex="-1">Raise a GDPR Request <a class="header-anchor" href="#raise-a-gdpr-request" aria-label="Permalink to &quot;Raise a GDPR Request&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>createGdprRequest</code> mutation raises a new GDPR data request for the authenticated customer. A new request is created with status <code>pending</code> and is tied to the logged-in customer. The result carries a one-time <code>successMessage</code> confirming the request was raised.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the mutation fails with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> in <code>errors[]</code>. The feature has been turned off on the admin side.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>String</code></td><td>✅ Yes</td><td>Request type — <code>delete</code> (delete account data) or <code>update</code> (update personal data). Optional in the schema but rejected when absent, so treat it as required.</td></tr><tr><td><code>message</code></td><td><code>String</code></td><td>✅ Yes</td><td>A message describing what the customer is requesting. Optional in the schema but rejected when absent.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>❌ No</td><td>Arbitrary string echoed back in the payload, for correlating a response with its request.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>gdprRequest._id</code></td><td><code>Int!</code></td><td>Numeric request ID.</td></tr><tr><td><code>gdprRequest.type</code></td><td><code>String!</code></td><td>Request type: <code>delete</code> or <code>update</code>.</td></tr><tr><td><code>gdprRequest.status</code></td><td><code>String!</code></td><td>Request status — <code>pending</code> for a freshly raised request.</td></tr><tr><td><code>gdprRequest.message</code></td><td><code>String!</code></td><td>The message supplied in the request.</td></tr><tr><td><code>gdprRequest.email</code></td><td><code>String!</code></td><td>Email address tied to the request.</td></tr><tr><td><code>gdprRequest.revokedAt</code></td><td><code>String</code></td><td>Timestamp when the request was revoked, or <code>null</code>.</td></tr><tr><td><code>gdprRequest.createdAt</code></td><td><code>String</code></td><td>Request creation timestamp.</td></tr><tr><td><code>gdprRequest.updatedAt</code></td><td><code>String</code></td><td>Request last update timestamp.</td></tr><tr><td><code>gdprRequest.successMessage</code></td><td><code>String</code></td><td>Confirmation message — present on create / revoke / delete results.</td></tr><tr><td><code>gdprRequest.customer</code></td><td><code>Customer</code></td><td>The customer who owns the request.</td></tr><tr><td><code>gdprRequest.customer._id</code></td><td><code>Int!</code></td><td>Numeric customer ID of the owner.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.html">List GDPR Requests</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.html">Revoke a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.html">Delete a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/">GDPR Requests Overview</a></li></ul>',13)]))}const m=t(s,[["render",o]]);export{h as __pageData,m as default};
